def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    day = day_context['day']
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    strong_pressure = 0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(bid)
                if bid >= 90:
                    strong_pressure += 1

    if budget <= 0:
        return 0.0

    if not alive:
        return float(min(budget, 20.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    supply_ratio = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY)
    if supply_ratio < 0:
        supply_ratio = 0.0
    if supply_ratio > 1:
        supply_ratio = 1.0

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 1

    if day >= 8:
        urgency += 1

    scarcity = 1.0 - supply_ratio

    if urgency >= 5:
        target = max(102.0, highest_prev + 4.0)
    elif urgency >= 3:
        target = max(88.0, avg_prev + 3.0, 72.0 + 18.0 * scarcity)
    else:
        if strong_pressure >= 2 and highest_prev >= 105.0 and supply >= 20:
            target = 18.0
        elif supply >= 23:
            target = max(32.0, avg_prev * 0.45)
        elif supply >= 20:
            target = max(48.0, avg_prev * 0.62)
        elif supply >= 17:
            target = max(62.0, avg_prev * 0.76)
        else:
            target = max(78.0, avg_prev * 0.9, highest_prev - 6.0)

    remaining_days = max(1, 10 - day)
    soft_cap = budget / float(remaining_days)
    if urgency >= 5:
        cap = max(soft_cap * 1.8, DAILY_SALARY * 1.45)
    elif urgency >= 3:
        cap = max(soft_cap * 1.35, DAILY_SALARY * 1.15)
    else:
        cap = max(soft_cap * 0.95, DAILY_SALARY * 0.9)

    bid = min(budget, target, cap)

    if hp <= 2 or no_water_days >= 2:
        bid = min(budget, max(bid, highest_prev + 2.0, 96.0))

    if budget < 60:
        bid = min(budget, max(0.0, budget - 1.0))

    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

