def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context.get('supply', 0.0)
    day = day_context.get('day', 0)

    hp = my_status.get('hp', 0)
    budget = my_status.get('budget', 0.0)
    no_water_days = my_status.get('no_water_days', 0)

    alive_opps = []
    for oid, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((oid, opp))

    if not alive_opps:
        return min(budget, DAILY_SALARY * 0.35)

    # Read yesterday bids from traces for immediate reaction
    prev_bids = []
    for oid, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Baseline bid target based on yesterday pressure
    if prev_bids:
        highest_prev_bid = max(prev_bids)
        avg_prev_bid = sum(prev_bids) / float(len(prev_bids))
    else:
        highest_prev_bid = 0.0
        avg_prev_bid = 0.0

    # Supply pressure: when supply is tight, bid more to avoid losing the water allocation
    # supply is within [15,25] in this meta-round.
    # tight_ratio near 1 when supply close to MIN_SUPPLY.
    tight_ratio = 1.0 - (float(supply) - float(MIN_SUPPLY)) / (float(MAX_SUPPLY) - float(MIN_SUPPLY))
    if tight_ratio < 0.0:
        tight_ratio = 0.0
    if tight_ratio > 1.0:
        tight_ratio = 1.0

    # Our urgency
    urgent = 0
    if hp <= 2:
        urgent = 2
    elif hp <= 4:
        urgent = 1
    if no_water_days >= 2:
        urgent = max(urgent, 2)

    # Strategy: bid slightly above the average of active opponents, but never exceed a cap.
    # If someone already bid extremely high yesterday, we try to contest but with a controlled cap.
    contest_factor = 0.08 + 0.12 * tight_ratio

    # Base candidate from opponent traces
    if prev_bids:
        target = avg_prev_bid * (1.0 + contest_factor)
        # If the highest bid was very high, nudge up slightly but don't chase blindly.
        if highest_prev_bid > avg_prev_bid * 1.15:
            target = max(target, avg_prev_bid + 0.5 * (highest_prev_bid - avg_prev_bid))
    else:
        target = DAILY_SALARY * (0.55 + 0.25 * tight_ratio)

    # Adjust for urgency
    if urgent == 2:
        target *= 1.25
    elif urgent == 1:
        target *= 1.10

    # Ensure we don't overbid relative to our budget.
    # Keep a safety reserve so we can continue bidding in later days.
    # Reserve fraction increases when hp is low.
    if hp <= 2:
        reserve_frac = 0.35
    elif hp <= 4:
        reserve_frac = 0.25
    else:
        reserve_frac = 0.18

    max_affordable = budget * (1.0 - reserve_frac)
    if max_affordable < 0.0:
        max_affordable = 0.0

    # Also cap by a fraction of daily salary to avoid catastrophic spend.
    # In medium scenario, winning typically requires contesting but not full spend.
    daily_cap = DAILY_SALARY * (0.95 if urgent == 2 else 0.75 if urgent == 1 else 0.6)

    bid = min(target, max_affordable, daily_cap, budget)

    # If budget is tiny, still bid something non-zero to avoid being fully outbid.
    if bid <= 0.0 and budget > 0.0:
        bid = min(budget, DAILY_SALARY * 0.1)

    return float(bid)
